use verus::*;

#[verus::verus]
pub fn determine_food_safety(x: i8, a: i8, b: i8) -> &'static str {
    // Precondition: x (threshold) is non-negative
    requires(x >= 0);

    // Compute days past as (b - a)
    let days_past = b - a;

    // Postconditions specify the returned string corresponds exactly 
    // to the value of days_past compared to 0 and x.
    ensures({
        (days_past <= 0 && result == "delicious") ||
        (days_past > 0 && days_past <= x && result == "safe") ||
        (days_past > x && result == "dangerous")
    });

    // Implementation:
    if days_past <= 0 {
        "delicious"
    } else if days_past <= x {
        "safe"
    } else {
        "dangerous"
    }
}